/* @lc app=leetcode id=2407 lang=kotlin */ class Solution { fun q(t: IntArray, l: Int, r: Int): Int = if (l > r) 0 else generateSequence(Triple(l + 131072, r + 1 + 131072, 0)) { (a, b, res) -> if (a >= b) null else (if (a % 2 == 1) maxOf(res, t[a]) else res).let { r2 -> (if (b % 2 == 1) maxOf(r2, t[b - 1]) else r2).let { r3 -> Triple((a + a % 2) / 2, (b - b % 2) / 2, r3) } } }.last().third fun upd(t: IntArray, x: Int, v: Int) = generateSequence(x + 131072) { it / 2 }.takeWhile { it >= 1 }.forEach { i -> t[i] = if (i == x + 131072) maxOf(t[i], v) else maxOf(t[2 * i], t[2 * i + 1]) } fun lengthOfLIS(nums: IntArray, k: Int): Int = IntArray(2 shl 17).let { t -> nums.maxOf { x -> (q(t, maxOf(1, x - k), x - 1) + 1).also { upd(t, x, it) } } } }